import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"二维装箱 BPP2D","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp2d/index.md","filePath":"zh-cn/frameworks/bpp2d/index.md"}'),d={name:"zh-cn/frameworks/bpp2d/index.md"};function i(l,t,n,h,c,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="二维装箱-bpp2d" tabindex="-1">二维装箱 BPP2D <a class="header-anchor" href="#二维装箱-bpp2d" aria-label="Permalink to &quot;二维装箱 BPP2D&quot;">​</a></h1><p>把已有矩形零件排到板面上，检查旋转、间距、越界和重叠，再比较板材消耗与余料。二维装箱不仅是画坐标，还需要需求覆盖、板型选择和最终校验。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>物品</td><td><code>ActualItem</code></td><td>形状、重量和旋转许可</td></tr><tr><td>板材类型</td><td><code>SheetType</code></td><td>宽高、承重、类型身份</td></tr><tr><td>候选排布</td><td><code>Layer</code></td><td>携带板材类型的放置集合</td></tr><tr><td>生成请求</td><td><code>Bpp2dLayerGenerationRequest</code></td><td>物品、板型、间距与候选限制</td></tr><tr><td>应用服务</td><td><code>ColumnGenerationApplicationService</code></td><td>生成、分配、装箱与 KPI / 渲染</td></tr></tbody></table><p>矩形支持可选 90° 旋转；圆形与混合形状属于后续专题。内部相交才算重叠，相切不算重叠。实际面积与外接面积应分别阅读。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>两种语言都有 <code>ColumnGenerationApplicationService</code>，但 Kotlin 的 solver 注入与 Rust 的 RMP/final executor 接口不同。Rust 不传求解器的退化执行不能解释为完成最终整数优化。</p><p>先理解候选层和终态几何校验，再接通受限主问题、定价和最终 MILP。框架负责这些领域步骤，业务调用方不应另写一套重叠约束。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>几何上放得下，不等于满足断头台裁切工艺。生产需求、切分树与卷材消耗见 <a href="./../csp2d/">CSP2D</a>。</li><li>圆形面积为实际圆面积，不能用外接矩形面积冒充装载率。</li><li>面积消耗、板数和板型成本是不同目标；加权和不是天然的严格词典序优化。</li><li>仅有候选生成或 mock 执行，不构成原生求解或完整问题最优性证据。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-layout.html">第一次二维排样</a>，从矩形和单板型开始。</li><li>修改旋转与间距，再引入多板型与成本。新生成策略应接生成器接口，而不是复制求解循环。</li><li>添加业务规则前，明确它约束单个候选还是多个候选的组合选择。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp2d/README_ch.md" target="_blank" rel="noreferrer">Kotlin API 与形状支持矩阵</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp2d/README_ch.md" target="_blank" rel="noreferrer">Rust API 与执行器契约</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">多板型、旋转与间距</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',17)])])}const f=a(d,[["render",i]]);export{u as __pageData,f as default};
